// Install dependencies:
// npm install carbon-components carbon-components-react react react-dom

import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
} from 'carbon-components-react';

function NumberInputExample() {
  const [value, setValue] = useState(50);

  // Carbon's onChange signature: (valueAsString, valueAsNumber) => void
  const handleChange = (_valueAsString, valueAsNumber) => {
    setValue(valueAsNumber);
  };

  return (
    <div style={{ padding: '2rem', maxWidth: '300px' }}>
      <NumberInput
        id="example-number-input"
        label="Number Input label"
        min={0}
        max={100}
        step={1}
        value={value}
        onChange={handleChange}
      >
        <NumberInputField />
        <NumberInputStepper>
          <NumberIncrementStepper />
          <NumberDecrementStepper />
        </NumberInputStepper>
      </NumberInput>
    </div>
  );
}

ReactDOM.render(<NumberInputExample />, document.getElementById('root'));
